package br.com.locago.atendimento; import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ComposicaoService{private final JdbcClient jdbc;private final ObjectMapper json;public ComposicaoService(JdbcClient j,ObjectMapper o){jdbc=j;json=o;}public List<Map<String,Object>>listar(){return jdbc.sql("select dados::text from composicao_catalogo where ativo order by dados->>'nome'").query(String.class).list().stream().map(this::ler).toList();}public Map<String,Object>salvar(Map<String,Object>d){String nome=String.valueOf(d.getOrDefault("nome","")).trim(),principal=String.valueOf(d.getOrDefault("principal","")).trim();if(nome.length()<3||principal.isBlank())throw new IllegalArgumentException("Informe nome e equipamento principal");String id=String.valueOf(d.getOrDefault("id","")).trim();if(id.isBlank())id="KIT-"+System.currentTimeMillis();d.put("id",id);try{jdbc.sql("insert into composicao_catalogo(id,dados) values(:i,cast(:d as jsonb)) on conflict(id) do update set dados=excluded.dados,atualizado_em=now()").param("i",id).param("d",json.writeValueAsString(d)).update();return d;}catch(Exception e){throw new IllegalArgumentException("Não foi possível salvar a composição");}}@SuppressWarnings("unchecked")private Map<String,Object>ler(String s){try{return json.readValue(s,Map.class);}catch(Exception e){throw new IllegalStateException(e);}}}
